window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-52d91754761be56d"]={"versions": [{"id": "FIG-52d91754761be56d", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendefinition im Rahmen eines Klassendiagramms (<code>class SecurityAccess</code>). Das Diagramm spezifiziert die AUTOSAR-Port-Interface-Definition <code>SecurityAccess_&lt;LEVEL&gt;</code> des Diagnostic Communication Managers (DCM) zur Anbindung von anwendungsspezifischen Sicherheitsmechanismen für den UDS-Dienst SecurityAccess (0x27) gemäß Anforderungen Dcm323 und Dcm324.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Client-Server-Interface <code>«interface» SecurityAccess_&lt;LEVEL&gt;</code> mit zwei synchronen Operationen:</p>\n<ul class=\"fig-list\"><li><code>CompareKey(return :Std_ReturnType, Key :uint8*)</code>: Operation zum Verifizieren des vom Diagnosetester übermittelten Schlüssels gegen das berechnete Sicherheitsgeheimnis.\n</li><li><code>GetSeed(return :Std_ReturnType, SecurityAccessRecord :uint8*, Seed :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>: Operation zur Abfrage eines Seeds vom Sicherheits-SW-C unter Übergabe optionaler Zugriffsdaten (<code>SecurityAccessRecord</code>), Generierung des <code>Seed</code> und optionaler Rückgabe eines negativen Fehlercodes (<code>ErrorCode</code>).\n</li></ul>\n<p class=\"fig-p\">Eingebettet ist das Interface in einen Diagrammrahmen mit dem Bezeichner <code>class SecurityAccess</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne explizite Zeit- oder Sequenzachsen. Der implizite UDS-Sicherheitsablauf bedingt zunächst den Aufruf von <code>GetSeed</code> zur Bereitstellung eines Seeds an den Tester, gefolgt von der Überprüfung des Schlüssels über <code>CompareKey</code>. Beide Aufrufe liefern den Ausführungsstatus über <code>Std_ReturnType</code> zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellendefinition für SW-Cs bzw. Applikationen, die Security-Levels im DCM bedienen. Die Kennzeichnung <code>&lt;LEVEL&gt;</code> dient als Platzhalter für das jeweilige Sicherheitsniveau. Implementierende Komponenten müssen die Operationen mit den exakten Typen (<code>Std_ReturnType</code>, Zeiger auf <code>uint8</code>, Zeiger auf <code>Dcm_NegativeResponseCodeType</code>) bereitstellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9a70e46acd8ef6c3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendefinition. Das Diagramm spezifiziert die AUTOSAR-Port-Interface-Definition <code>«interface» SecurityAccess_&lt;LEVEL&gt;</code> des Diagnostic Communication Managers (DCM) zur Anbindung von anwendungsspezifischen Sicherheitsmechanismen für den UDS-Dienst SecurityAccess (0x27) gemäß Anforderungen Dcm323 und Dcm324.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Client-Server-Interface <code>«interface» SecurityAccess_&lt;LEVEL&gt;</code> mit zwei synchronen Operationen:</p>\n<ul class=\"fig-list\"><li><code>CompareKey(return :Std_ReturnType, Key :uint8*)</code>: Operation zum Verifizieren des vom Diagnosetester übermittelten Schlüssels gegen das berechnete Sicherheitsgeheimnis.\n</li><li><code>GetSeed(return :Std_ReturnType, SecurityAccessRecord :uint8*, Seed :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>: Operation zur Abfrage eines Seeds vom Sicherheits-SW-C unter Übergabe optionaler Zugriffsdaten (<code>SecurityAccessRecord</code>), Generierung des <code>Seed</code> und optionaler Rückgabe eines negativen Fehlercodes (<code>ErrorCode</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne explizite Zeit- oder Sequenzachsen. Der implizite UDS-Sicherheitsablauf bedingt zunächst den Aufruf von <code>GetSeed</code> zur Bereitstellung eines Seeds an den Tester, gefolgt von der Überprüfung des Schlüssels über <code>CompareKey</code>. Beide Aufrufe liefern den Ausführungsstatus über <code>Std_ReturnType</code> zurück.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellendefinition für SW-Cs bzw. Applikationen, die Security-Levels im DCM bedienen. Die Kennzeichnung <code>&lt;LEVEL&gt;</code> dient als Platzhalter für das jeweilige Sicherheitsniveau. Implementierende Komponenten müssen die Operationen mit den exakten Typen (<code>Std_ReturnType</code>, Zeiger auf <code>uint8</code>, Zeiger auf <code>Dcm_NegativeResponseCodeType</code>) bereitstellen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-52d91754761be56d", "to": "FIG-9a70e46acd8ef6c3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Äußerer UML-Klassendiagramm-Rahmen <code>class SecurityAccess</code> entfernt; das Interface <code>«interface» SecurityAccess_&lt;LEVEL&gt;</code> wird freistehend ohne umgebenden Diagramm-Frame dargestellt.\n</li><li>Interface-Name <code>SecurityAccess_&lt;LEVEL&gt;</code> von fett/kursiver Schriftart auf nicht-kursive Normalschriftart umgestellt.\n</li></ul>"}]};
